import { useEffect, useState } from 'react'
import { Navbar } from './components/Navbar'
import { Footer } from './components/Footer'
import { HomePage } from './pages/HomePage'
import { CoursesPage } from './pages/CoursesPage'
import { DownloadsPage } from './pages/DownloadsPage'
import { MembershipsPage } from './pages/MembershipsPage'
import { CoachingPage } from './pages/CoachingPage'

type Page = 'home' | 'courses' | 'downloads' | 'memberships' | 'coaching'

function getPageFromPath(): Page {
  const path = window.location.pathname
  if (path.includes('online-courses')) return 'courses'
  if (path.includes('digital-downloads')) return 'downloads'
  if (path.includes('memberships')) return 'memberships'
  if (path.includes('coaching')) return 'coaching'
  return 'home'
}

export default function App() {
  const [page, setPage] = useState<Page>(getPageFromPath)

  useEffect(() => {
    const handlePopState = () => setPage(getPageFromPath())
    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [])

  const navigate = (href: string) => {
    const path = href.replace('.html', '')
    let target: Page = 'home'
    if (path.includes('online-courses')) target = 'courses'
    else if (path.includes('digital-downloads')) target = 'downloads'
    else if (path.includes('memberships')) target = 'memberships'
    else if (path.includes('coaching')) target = 'coaching'
    setPage(target)
    window.history.pushState({}, '', href)
  }

  return (
    <div className="grain min-h-screen bg-background">
      <Navbar navigate={navigate} currentPage={page} />
      <main>
        {page === 'home' && <HomePage />}
        {page === 'courses' && <CoursesPage />}
        {page === 'downloads' && <DownloadsPage />}
        {page === 'memberships' && <MembershipsPage />}
        {page === 'coaching' && <CoachingPage />}
      </main>
      <Footer navigate={navigate} />
    </div>
  )
}

