    if (href === 'index.html') return currentPage === 'home'
    if (href === 'online-courses.html') return currentPage === 'courses'
    if (href === 'digital-downloads.html') return currentPage === 'downloads'
    if (href === 'memberships.html') return currentPage === 'memberships'
    if (href === 'coaching.html') return currentPage === 'coaching'
    return false
